211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
214	        HttpHeaders headers = new HttpHeaders();
215	        Visit visit = visitMapper.toVisit(visitFieldsDto);
216	        Pet pet = new Pet();
217	        pet.setId(petId);
218	        visit.setPet(pet);
219	        this.clinicService.saveVisit(visit);
220	        VisitDto visitDto = visitMapper.toVisitDto(visit);
221	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
222	            .buildAndExpand(visit.getId()).toUri());
223	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
224	    }
225	
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
230	        Owner owner = this.clinicService.findOwnerById(ownerId);
231	        if (owner != null) {
232	            Pet pet = owner.getPet(petId);
233	            if (pet != null) {
234	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	    }
239	
240	    /**
241	     * Builds the owner's customer code as {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the
242	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
243	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
244	     *
245	     * @param lastName the owner's last name (already validated non-blank)
246	     * @return the formatted customer code for the owner being created
247	     */
248	    private String nextCustomerCode(String lastName) {
249	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
250	        int sequence = this.clinicService.findAllOwners().size() + 1;
251	        return String.format("%s-%04d", last3, sequence);
252	    }
253	
254	    /**
255	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
256	     * whitespace-only), so the caller can reject the request listing every offending field.
257	     */
258	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
259	        if (value == null || value.isBlank()) {
260	            missingFields.add(fieldName);
261	        }
262	    }
263	
264	    /**
265	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
266	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
267	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
268	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
269	     * {@code "+61412345678"}.
270	     *
271	     * @param telephone the raw telephone value from the request
272	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
273	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
274	     */
275	    private static String normalizeTelephone(String telephone) {
276	        String e164 = toE164(telephone);
277	        if (e164 == null) {
278	            throw new InvalidFieldValueException("telephone",
279	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
280	        }
281	        return e164;
282	    }
283	
284	    /**
285	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
286	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
287	     * owners' stored numbers when detecting duplicates.
288	     */
289	    private static String toE164(String telephone) {
290	        if (telephone == null) {
291	            return null;
292	        }
293	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
294	        String digits;
295	        if (cleaned.startsWith("+")) {
296	            digits = cleaned.substring(1);
297	        } else {
298	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
299	            digits = "61" + national;
300	        }
301	        if (!digits.matches("[0-9]{8,15}")) {
302	            return null;
303	        }
304	        return "+" + digits;
305	    }
306	
307	    /**
308	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
309	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
310	     *
311	     * @param email the raw email value from the request (already known to be non-null)
312	     * @return the lower-cased email to be stored and returned
313	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
314	     */
315	    private static String normalizeEmail(String email) {
316	        String trimmed = email.trim();
317	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
318	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
319	        }
320	        return trimmed.toLowerCase(Locale.ROOT);
321	    }
322	
323	    /**
324	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
325	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
326	     *
327	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
328	     * @throws DuplicateTelephoneException if another owner already uses this telephone
329	     */
330	    private void requireUniqueTelephone(String normalizedTelephone) {
331	        boolean taken = this.clinicService.findAllOwners().stream()
332	            .map(Owner::getTelephone)
333	            .map(OwnerRestControllerV1::toE164)
334	            .filter(existing -> existing != null)
335	            .anyMatch(normalizedTelephone::equals);
336	        if (taken) {
337	            throw new DuplicateTelephoneException(normalizedTelephone);
338	        }
339	    }
340	
341	    /**
342	     * Rejects the request when another owner already shares this household, i.e. has both the same
343	     * last name and the same address once each value is normalized (trimmed, internal whitespace
344	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
345	     * when the request opts in via {@code sharesHousehold}.
346	     *
347	     * @param lastName the incoming owner's last name (already validated non-blank)
348	     * @param address the incoming owner's address (already validated non-blank)
349	     * @throws DuplicateHouseholdException if another owner already has this last name and address
350	     */
351	    private void requireUniqueHousehold(String lastName, String address) {
352	        String normalizedLastName = normalizeForHousehold(lastName);
353	        String normalizedAddress = normalizeForHousehold(address);
354	        boolean taken = this.clinicService.findAllOwners().stream()
355	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
356	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress));
357	        if (taken) {
358	            throw new DuplicateHouseholdException(lastName, address);
359	        }
360	    }
361	
362	    /**
363	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
364	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
365	     * comparisons are case-insensitive.
366	     */
367	    private static String normalizeForHousehold(String value) {
368	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
369	    }
370	}
